// Extract message and validate sender
const ADMIN_CHAT_ID = '8355378781';

const msg = $input.first().json.message;
const chatId = String(msg.chat.id);
const text = msg.text || '';
const firstName = msg.from.first_name || 'User';

// Security: only respond to admin
if (chatId !== ADMIN_CHAT_ID) {
  return [{ json: { _route: 'unauthorized', chatId, text } }];
}

// Parse command
let instruction = text;
let command = 'agent';

if (text.startsWith('/')) {
  const parts = text.split(' ');
  command = parts[0].replace('/', '').toLowerCase();
  instruction = parts.slice(1).join(' ');
}

return [{ json: {
  _route: command,
  chatId,
  instruction,
  firstName,
  rawText: text
}}];

// Format agent response for Telegram
const data = $input.first().json;
let msg = '';

if (data.status === 'completed') {
  msg = '✅ *Task Completed*\n\n';
  msg += `📋 ${data.instruction}\n\n`;
  if (data.results && data.results.length > 0) {
    for (const r of data.results) {
      const icon = r.success ? '✓' : '✗';
      msg += `${icon} Step ${r.step}: \`${r.tool}\`\n`;
      if (r.result) msg += `  → ${r.result}\n`;
      if (r.error) msg += `  ⚠️ ${r.error}\n`;
    }
  }
  msg += `\n⏱️ ${data.duration_ms}ms`;
} else if (data.status === 'blocked') {
  msg = '🚫 *Action Blocked*\n\n';
  msg += `Reason: ${data.error}`;
} else if (data.status === 'needs_approval') {
  msg = '⚠️ *Approval Required*\n\n';
  msg += `${data.error}\n\nReply /approve or /reject`;
} else if (data.status === 'failed') {
  msg = '❌ *Task Failed*\n\n';
  msg += `Error: ${data.error}`;
} else if (data.error) {
  msg = '❌ *Error*\n\n' + data.error;
} else {
  msg = '🤷 Unexpected response:\n' + JSON.stringify(data).substring(0, 500);
}

const chatId = $('Parse Command').first().json.chatId;
return [{ json: { chatId, msg } }];

// Format health status for Telegram
const data = $input.first().json;
const status = data.status === 'healthy' ? '🟢' : '🔴';
let msg = `${status} *Agent Status*\n\n`;
msg += `Status: ${data.status}\n`;
msg += `Uptime: ${Math.floor(data.uptime_seconds / 60)} minutes\n`;
msg += `Ollama: ${data.ollama?.connected ? '✅ Connected' : '❌ Disconnected'}\n`;
msg += `Models: ${data.ollama?.models?.join(', ') || 'none'}\n`;
msg += `Tools: ${data.tools_registered} registered`;

const chatId = $('Parse Command').first().json.chatId;
return [{ json: { chatId, msg } }];
